import sys
from rich.console import Console
import os

class ProxyFile:
    def __init__(self, file):
        self.file = file

    def write(self, data):
        self.file.write(data)

    def flush(self):
        self.file.flush()

    def fileno(self):
        return self.file.fileno()

    # explicitly NOT implementing isatty()

def test_proxy_isatty():
    # Wrap stdout in our proxy
    proxy = ProxyFile(sys.stdout)
    console = Console(file=proxy)

    # Since we are likely running in a terminal or a CI environment that 
    # simulates one/has a valid fd, we check if os.isatty(sys.stdout.fileno()) 
    # matches Console.is_terminal
    expected = os.isatty(sys.stdout.fileno())
    actual = console.is_terminal

    print(f"Expected: {expected}, Actual: {actual}")
    assert actual == expected, f"Expected {expected}, got {actual}"
    print("Test passed!")

if __name__ == "__main__":
    try:
        test_proxy_isatty()
    except AssertionError as e:
        print(f"Test failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

